-- 로고 보관함 · 보이기 규칙 (docs/features/site-logo-library-contract.md)
--
-- 사이트 로고를 「묶음(한 벌 = 4칸)」으로 보관하고 평소 · 기념일 · 회원 성별에 따라 다른 묶음을 보인다. 4칸의 뜻(① 한글·밝은 ② 한글·어두운 ③ 영문·밝은 ④ 영문·어두운)과
-- 칸마다 「그림 파일 하나 또는 SVG 소스 하나」 규칙은 V237 과 같다(site-logo-variants-contract.md).
--
-- 1) site_logo_bundles — 묶음. 기본 제공 둘(built_in_key CHARACTER · WORDMARK, id 1 · 2 고정)은 여기서 넣어 모든 설치에 늘 있다(고치지 못한다 — 서버가 거절).
--    올린 묶음의 id 는 앱이 매긴다(Snowflake). 묶음은 지우지 않는다(보관).
-- 2) site_settings — 평소 로고(logo_default_bundle_id, 처음 값 = 캐릭터 로고)와 성별 규칙(logo_male_bundle_id · logo_female_bundle_id, NULL = 고르지 않음).
-- 3) 옮기기 — 지금 4칸(V12 · V237)이 모두 비었거나 기본 캐릭터 그림(V246 · 설치기가 넣은 것) 그대로면 평소 로고 = 캐릭터 로고.
--    운영자가 올린 그림이 한 칸이라도 있으면 그 4칸을 올린 묶음 「이전 로고」(id 3)로 옮겨 평소 로고로 둔다 — 그림 파일(files.id)은 묶음 칸이 그대로 가리킨다.
--    옮긴 뒤 옛 칸(logo_file_id · logo_svg · logo_{ko_dark,en_light,en_dark}_* · logo_name_included)은 지운다 — 로고의 원천은 묶음 하나다.
-- 4) site_logo_rules — 기념일 규칙(sort_order 차례 = 우선순위). 날짜 직접(DATES — 매년 반복이면 월·일 'MM-DD', 아니면 'YYYY-MM-DD') 또는 쉬는 날 표의 이름(HOLIDAY).

CREATE TABLE site_logo_bundles (
    id                bigint       PRIMARY KEY,
    name              varchar(30)  NOT NULL,
    built_in_key      varchar(20),                                  -- 기본 제공 묶음만: CHARACTER · WORDMARK
    name_in_logo      boolean      NOT NULL DEFAULT false,          -- 로고 그림에 사이트 이름이 들어 있는가(켜져 있으면 옆 이름 글자를 숨긴다)
    ko_light_file_id  bigint       REFERENCES files (id),
    ko_light_svg      text,
    ko_dark_file_id   bigint       REFERENCES files (id),
    ko_dark_svg       text,
    en_light_file_id  bigint       REFERENCES files (id),
    en_light_svg      text,
    en_dark_file_id   bigint       REFERENCES files (id),
    en_dark_svg       text,
    created_by        bigint       REFERENCES operators (id) ON DELETE SET NULL,
    created_at        timestamptz  NOT NULL DEFAULT now(),
    updated_at        timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uq_site_logo_bundles_built_in UNIQUE (built_in_key),
    CONSTRAINT ck_site_logo_bundles_built_in CHECK (built_in_key IS NULL OR built_in_key IN ('CHARACTER', 'WORDMARK')),
    CONSTRAINT ck_site_logo_bundles_name CHECK (length(btrim(name)) BETWEEN 1 AND 30),
    CONSTRAINT ck_site_logo_bundles_ko_light_one CHECK (ko_light_file_id IS NULL OR ko_light_svg IS NULL),
    CONSTRAINT ck_site_logo_bundles_ko_dark_one CHECK (ko_dark_file_id IS NULL OR ko_dark_svg IS NULL),
    CONSTRAINT ck_site_logo_bundles_en_light_one CHECK (en_light_file_id IS NULL OR en_light_svg IS NULL),
    CONSTRAINT ck_site_logo_bundles_en_dark_one CHECK (en_dark_file_id IS NULL OR en_dark_svg IS NULL),
    CONSTRAINT ck_site_logo_bundles_ko_light_svg_len CHECK (ko_light_svg IS NULL OR char_length(ko_light_svg) BETWEEN 1 AND 100100),
    CONSTRAINT ck_site_logo_bundles_ko_dark_svg_len CHECK (ko_dark_svg IS NULL OR char_length(ko_dark_svg) BETWEEN 1 AND 100100),
    CONSTRAINT ck_site_logo_bundles_en_light_svg_len CHECK (en_light_svg IS NULL OR char_length(en_light_svg) BETWEEN 1 AND 100100),
    CONSTRAINT ck_site_logo_bundles_en_dark_svg_len CHECK (en_dark_svg IS NULL OR char_length(en_dark_svg) BETWEEN 1 AND 100100)
);

-- 기본 제공 묶음 — 그림은 server/api install-presets/brand/logo-*.svg · wordmark-*.svg(앱 public/brand/irobit-logo-*.svg · irobit-wordmark-*.svg 와 같다, 원본 robotikon/logo/).
-- 그림을 바꾸려면 새 마이그레이션이 이 두 줄의 SVG 칸을 고친다.
