ALTER TABLE site_settings ADD COLUMN logo_default_bundle_id bigint NOT NULL DEFAULT 1 REFERENCES site_logo_bundles (id);
ALTER TABLE site_settings ADD COLUMN logo_male_bundle_id bigint REFERENCES site_logo_bundles (id);
ALTER TABLE site_settings ADD COLUMN logo_female_bundle_id bigint REFERENCES site_logo_bundles (id);

-- 옮기기 — 운영자가 올린 그림이 있는 사이트만 「이전 로고」 묶음을 만든다.
-- 「기본 캐릭터 그림 그대로」 = 네 칸이 모두 SVG 이고 그 지문(md5, 줄 끝 CR 은 빼고)이 기본 그림의 것일 때.
-- 기본 그림 12장: V246 이 넣은 4장 · 2026-11-18 마스코트를 줄이기 직전의 4장(개발 중 설치기가 넣었을 수 있다) · 위 CHARACTER 묶음의 지금 4장.
INSERT INTO site_logo_bundles (id, name, name_in_logo, ko_light_file_id, ko_light_svg, ko_dark_file_id, ko_dark_svg, en_light_file_id, en_light_svg,
                               en_dark_file_id, en_dark_svg, created_by)
SELECT 3, '이전 로고', s.logo_name_included, s.logo_file_id, s.logo_svg, s.logo_ko_dark_file_id, s.logo_ko_dark_svg, s.logo_en_light_file_id, s.logo_en_light_svg,
       s.logo_en_dark_file_id, s.logo_en_dark_svg, (SELECT o.id FROM operators o WHERE o.id = s.updated_by)
  FROM site_settings s
 WHERE s.id = 1
   AND NOT (s.logo_file_id IS NULL AND s.logo_svg IS NULL AND s.logo_ko_dark_file_id IS NULL AND s.logo_ko_dark_svg IS NULL
            AND s.logo_en_light_file_id IS NULL AND s.logo_en_light_svg IS NULL AND s.logo_en_dark_file_id IS NULL AND s.logo_en_dark_svg IS NULL)
   AND NOT (s.logo_svg IS NOT NULL AND s.logo_ko_dark_svg IS NOT NULL AND s.logo_en_light_svg IS NOT NULL AND s.logo_en_dark_svg IS NOT NULL
            AND md5(replace(s.logo_svg, E'\r', '')) IN ('070bf971f689f0ab2257a280a0556d00', '529092a2af36e4be85876b48dbd2c6ee', '25f25b843f4520c4718ad5d2a708f3d4', '4887dd505ec5eea3bb9baf7976577f15', 'a63d7f624f36005218b4d7a635ba73a2', '63d4392cf4234ef450d3bbd844ecc837', '03a4de03ced76c9b723644d32de3bc56', '645df68ac3621bab3506c0f07adda376', 'da914bafc6030d89a837923c9ca61ceb', '378ebe751eb3fb9476d709e107bb98f7', '78c3194d5ec7e25d7adbdfdfe5d8a1f0', '5cee1083117148be240045ba62c12e8b')
            AND md5(replace(s.logo_ko_dark_svg, E'\r', '')) IN ('070bf971f689f0ab2257a280a0556d00', '529092a2af36e4be85876b48dbd2c6ee', '25f25b843f4520c4718ad5d2a708f3d4', '4887dd505ec5eea3bb9baf7976577f15', 'a63d7f624f36005218b4d7a635ba73a2', '63d4392cf4234ef450d3bbd844ecc837', '03a4de03ced76c9b723644d32de3bc56', '645df68ac3621bab3506c0f07adda376', 'da914bafc6030d89a837923c9ca61ceb', '378ebe751eb3fb9476d709e107bb98f7', '78c3194d5ec7e25d7adbdfdfe5d8a1f0', '5cee1083117148be240045ba62c12e8b')
            AND md5(replace(s.logo_en_light_svg, E'\r', '')) IN ('070bf971f689f0ab2257a280a0556d00', '529092a2af36e4be85876b48dbd2c6ee', '25f25b843f4520c4718ad5d2a708f3d4', '4887dd505ec5eea3bb9baf7976577f15', 'a63d7f624f36005218b4d7a635ba73a2', '63d4392cf4234ef450d3bbd844ecc837', '03a4de03ced76c9b723644d32de3bc56', '645df68ac3621bab3506c0f07adda376', 'da914bafc6030d89a837923c9ca61ceb', '378ebe751eb3fb9476d709e107bb98f7', '78c3194d5ec7e25d7adbdfdfe5d8a1f0', '5cee1083117148be240045ba62c12e8b')
            AND md5(replace(s.logo_en_dark_svg, E'\r', '')) IN ('070bf971f689f0ab2257a280a0556d00', '529092a2af36e4be85876b48dbd2c6ee', '25f25b843f4520c4718ad5d2a708f3d4', '4887dd505ec5eea3bb9baf7976577f15', 'a63d7f624f36005218b4d7a635ba73a2', '63d4392cf4234ef450d3bbd844ecc837', '03a4de03ced76c9b723644d32de3bc56', '645df68ac3621bab3506c0f07adda376', 'da914bafc6030d89a837923c9ca61ceb', '378ebe751eb3fb9476d709e107bb98f7', '78c3194d5ec7e25d7adbdfdfe5d8a1f0', '5cee1083117148be240045ba62c12e8b'));

UPDATE site_settings SET logo_default_bundle_id = 3 WHERE id = 1 AND EXISTS (SELECT 1 FROM site_logo_bundles WHERE id = 3);

-- 옛 4칸 — 값은 위에서 묶음으로 옮겼다(칸에 걸린 CHECK · 외래키는 칸과 함께 사라진다)
ALTER TABLE site_settings
    DROP COLUMN logo_file_id, DROP COLUMN logo_svg,
    DROP COLUMN logo_ko_dark_file_id, DROP COLUMN logo_ko_dark_svg,
    DROP COLUMN logo_en_light_file_id, DROP COLUMN logo_en_light_svg,
    DROP COLUMN logo_en_dark_file_id, DROP COLUMN logo_en_dark_svg,
    DROP COLUMN logo_name_included;

CREATE TABLE site_logo_rules (
    id            bigint       PRIMARY KEY,
    sort_order    integer      NOT NULL,                            -- 작은 수가 먼저(위 줄이 이긴다)
    name          varchar(30)  NOT NULL,
    enabled       boolean      NOT NULL DEFAULT true,
    mode          varchar(10)  NOT NULL,                            -- DATES(날짜 직접) · HOLIDAY(쉬는 날 표의 이름)
    start_date    varchar(10),                                      -- DATES: yearly 면 'MM-DD', 아니면 'YYYY-MM-DD'(끝 날 포함)
    end_date      varchar(10),                                      --        yearly 에서 끝이 시작보다 앞이면 해를 넘기는 기간(12-30 ~ 01-02)
    yearly        boolean      NOT NULL DEFAULT false,
    holiday_name  varchar(40),                                      -- HOLIDAY: site_holidays.name — 그 이름의 날마다 걸린다
    bundle_id     bigint       NOT NULL REFERENCES site_logo_bundles (id),
    created_at    timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT ck_site_logo_rules_mode CHECK (mode IN ('DATES', 'HOLIDAY')),
    CONSTRAINT ck_site_logo_rules_name CHECK (length(btrim(name)) BETWEEN 1 AND 30),
    CONSTRAINT ck_site_logo_rules_shape CHECK (
        (mode = 'DATES' AND start_date IS NOT NULL AND end_date IS NOT NULL AND holiday_name IS NULL)
        OR (mode = 'HOLIDAY' AND holiday_name IS NOT NULL AND start_date IS NULL AND end_date IS NULL AND yearly = false))
);
